// AUTO-GENERATED from static/matchaTonoki-logo.svg (the drawn brand logo).
// Do not edit by hand — re-run the bake described in
// .agents/docs/project-status-2026-08-25b.md and paste the result.
//
// The stone is rebuilt as a bevelled slab with the artwork painted on its two
// faces, the way an enamel pin is made. Three things this bake depends on:
//
//   - The ink outline is NOT a painted layer. The base slab is ink-coloured
//     and the colour fills are inset from the silhouette, so the unpainted
//     margin showing around them IS the outline. One less layer, and the line
//     wraps the bevel instead of stopping dead at the edge.
//   - Every paint layer is clipped to `silhouette.buffer(-BEVEL_SIZE)`. Paint
//     crossing the bevel would hang off the rounded edge in mid-air, so the
//     bevel is baked into the data; the two must change together.
//   - Contours are simplified at 0.6 artwork units. Below that the point count
//     climbs fast for detail nobody can resolve at this scale.
//
// Coordinates are normalised to a 3.9-unit height, centred on the origin — the
// same space as the low-poly bake, so the scene's layout knobs carry over.

/** Bevel the paint was clipped against. Changing this alone WILL float the paint. */
export const MAGATAMA_ICON_BEVEL_SIZE = 0.05;

export interface MagatamaIconLayer {
  /** `base` is the slab; `front` and `back` are paint laid on its flat faces. */
  role: 'base' | 'front' | 'back';
  /** Steps of `paintGap` off the face. Colour fills sit at 1, the ink on 2. */
  tier: number;
  color: string;
  /** Polygons; each is `[outer, ...holes]`, each ring a flat `[x, y, …]`. */
  contours: number[][][];
}

